function testAutomaticEnemySpawning() {
    const earthTheme = normalizeGeneratorTheme(JSON.parse(readFileSync(new URL("../assets/level-generator-themes/earth-cavern.json", import.meta.url), "utf8")));
    const assetCatalog = normalizeGenerationAssetCatalog(JSON.parse(readFileSync(new URL("../assets/level-generator-platforms.json", import.meta.url), "utf8")));
    const enemyIds = ["enemy_001", "enemy_010", "enemy_011", "enemy_012", "enemy_020"];
    assert.deepEqual(normalizeAutoSpawnEnemies(null), DEFAULT_AUTO_SPAWN_ENEMIES, "automatic enemy spawning should default to disabled, zero percent, and enemies 001-999");
    assert.deepEqual(
        resolveAutoSpawnEnemyIds({ enabled: true, probabilityPercent: 25, enemyPool: "1-20,!10,!19" }, JSON.parse(readFileSync("./assets/ct_enemies_001.json", "utf8"))).resolvedIds,
        ["enemy_001", "enemy_002", "enemy_011", "enemy_012", "enemy_020"],
        "automatic spawning should share the level generator enemy-pool expression format"
    );

    const risingStylesSeen = new Set();
    for (const seed of ["cave-0", "cave-3", "cave-a"]) {
        const draft = generateAutomaticLevelDraft({
            theme: earthTheme,
            assetCatalog,
            seed,
            settings: { ...earthTheme.defaults, length: "grand", safety: 1 },
            implementations: {
                ...earthTheme.implementations,
                route: "rising-cave-route-v1",
                encounters: "not-generated-yet",
                rewards: "not-generated-yet",
                validation: "the-path74-cavern-validation-v4"
            },
            availableEnemyIds: enemyIds,
            destinationLevel: "level_002"
        });
        assert.equal(draft.generation.validation.valid, true, `Rising Cave cavern ${seed} should validate: ${draft.generation.validation.errors.join(" ")}`);
        assert.equal(draft.generation.cavern.macroPatternId, "rising-cave", "Rising Cave cave generation should retain the route pattern");
        assert.ok(draft.generation.cavern.bounds.h > 2400, "Rising Cave cave perimeter should span the two upward screen sections");
        assert.ok(draft.generation.cavern.stamps.every((stamp) => stamp.kind !== "wideUpperRoom" && stamp.kind !== "domedCeilingExpansion"), "Rising Cave should use a route-following contour instead of the default broad dome expansion");
        const styles = Object.values(draft.generation.traversal.verticalTraversalStyles || {});
        assert.equal(styles.length, 2, "Rising Cave should assign a traversal style to both upward shafts");
        styles.forEach((style) => risingStylesSeen.add(style));
        const greenSupports = draft.generation.traversal.supports.filter((support) => support.verticalClimbPlatform);
        assert.ok(greenSupports.every((support) => support.collisionMode === "oneWay"), "Rising Cave climbing platforms should always use green one-way collision lines");
        for (const [edgeId, style] of Object.entries(draft.generation.traversal.verticalTraversalStyles || {})) {
            const edgeSupports = draft.generation.traversal.supports.filter((support) => support.routeEdgeId === edgeId);
            const moving = edgeSupports.filter((support) => support.moving && support.movementAxis === "vertical");
            const green = edgeSupports.filter((support) => support.verticalClimbPlatform);
            if (style === "elevator") assert.equal(moving.length, 1, "elevator shafts should contain one moving platform");
            if (style === "platforms") assert.ok(!moving.length && green.length >= 5, "platform shafts should use a complete green switchback and no elevator");
            if (style === "mix") assert.ok(moving.length === 1 && green.length >= 5, "mixed shafts should contain both an elevator and a green switchback");
        }
    }
    assert.deepEqual([...risingStylesSeen].sort(), ["elevator", "mix", "platforms"], "Rising Cave sample seeds should cover elevator, platform, and mixed vertical shafts");

    const serpentineDraft = generateAutomaticLevelDraft({
        theme: earthTheme,
        assetCatalog,
        seed: "serp-c-0",
        settings: { ...earthTheme.defaults, length: "standard", winding: 0.7, safety: 1 },
        implementations: {
            ...earthTheme.implementations,
            route: "serpentine-cave-route-v1",
            encounters: "not-generated-yet",
            rewards: "not-generated-yet",
            validation: "the-path74-cavern-validation-v4"
        },
        availableEnemyIds: enemyIds,
        destinationLevel: "level_002"
    });
    assert.equal(serpentineDraft.generation.validation.valid, true, `Serpentine Cave draft should validate: ${serpentineDraft.generation.validation.errors.join(" ")}`);
    assert.equal(serpentineDraft.generation.cavern.macroPatternId, "serpentine-cave", "Serpentine Cave generation should retain its route pattern");
    assert.ok(serpentineDraft.generation.cavern.stamps.every((stamp) => stamp.kind !== "wideUpperRoom" && stamp.kind !== "domedCeilingExpansion"), "Serpentine Cave should use a narrow route-following contour instead of the default broad dome expansion");
    assert.ok((serpentineDraft.generation.route.macro.shortDropCount || 0) >= 0, "Serpentine Cave smoke seed should keep valid drop metadata even when that particular seed rolls no short drop");

    const editorHtml = readFileSync(new URL("../level-editor.html", import.meta.url), "utf8");
    assert.ok(editorHtml.includes('id="auto-spawn-enemies-enabled"'), "Level Editor should expose the automatic enemy spawn switch");
    assert.ok(editorHtml.includes('id="auto-spawn-enemies-probability"'), "Level Editor should expose the per-second percentage");
    assert.ok(editorHtml.includes('id="auto-spawn-enemies-probability" type="number" min="0" max="100" step="1" value="10"'), "new editor levels should offer a moderate ten-percent spawn chance when the feature is enabled");
    assert.ok(editorHtml.includes('probabilityPercent: 10'), "the Level Editor's empty-level model should preserve the ten-percent checkbox-ready default");
    assert.ok(editorHtml.includes('id="auto-spawn-enemies-pool"'), "Level Editor should expose the generator-format enemy pool");
    assert.ok(editorHtml.includes("refreshAutoSpawnEnemyPreview"), "Level Editor should preview the resolved enemy pool");
    const bootstrapSource = readFileSync(new URL("../src/browser/game-bootstrap.js", import.meta.url), "utf8");
    const rendererSource = readFileSync(new URL("../src/presentation/canvas-renderer.js", import.meta.url), "utf8");
    assert.ok(bootstrapSource.includes("enemyCharacterProjectUrls"), "browser startup should derive renderable character projects from the enemy catalog");
    assert.ok(rendererSource.includes("options.enemyCharacterUrls"), "renderer startup should accept the catalog-derived enemy character list");

    const authoredLevel = JSON.parse(readFileSync("./assets/level_t01.json", "utf8"));
    assert.deepEqual(authoredLevel.autoSpawnEnemies, DEFAULT_AUTO_SPAWN_ENEMIES, "authored levels should make the disabled defaults explicit");

    const rightward = createAutomaticEnemySpawnTestState();
    for (let step = 0; step < 122; step += 1) stepSimulation(rightward, createInputFrame(), FIXED_DT);
    assert.equal(rightward.world.autoSpawnEnemies.rollCount, 2, "automatic enemy spawning should roll once per second");
    assert.equal(rightward.world.autoSpawnEnemies.spawnCount, 2, "a 100 percent chance should produce one enemy on each successful one-second roll");
    const firstRightSpawn = rightward.debug.lastEvents.find((event) => event.type === "AUTO_ENEMY_SPAWNED");
    const firstRightEnemy = rightward.enemies.find((enemy) => enemy.id === firstRightSpawn?.enemyId);
    assert.ok(firstRightSpawn, "successful automatic spawning should emit a diagnostic event");
    assert.equal(firstRightSpawn.direction, 1, "an exit to the right should produce a forward right-side spawn");
    assert.ok(firstRightSpawn.distanceBeyondScreen >= 40 && firstRightSpawn.distanceBeyondScreen <= 400, "spawn distance should be 10-100 percent of the 400-pixel viewport beyond the screen edge");
    assert.equal(firstRightEnemy.enemyDefinitionId, "enemy_001", "the configured pool should select only eligible catalog enemies");
    assert.equal(firstRightEnemy.strategy, "hunter", "spawned ground enemies should use hunter navigation");
    assert.equal(firstRightEnemy.alerted, true, "spawned enemies should already have noticed the player");
    assert.equal(firstRightEnemy.engaged, true, "spawned enemies should immediately pursue the player");
    assert.equal(firstRightEnemy.lastSeenPlayerX, rightward.player.currentTransform.x, "spawned hunters should remember the player's current position");

    const leftward = createAutomaticEnemySpawnTestState({ exitX: -4000, enemyPool: "10", randomSeed: 321 });
    for (let step = 0; step < 62; step += 1) stepSimulation(leftward, createInputFrame(), FIXED_DT);
    const leftSpawn = leftward.debug.lastEvents.find((event) => event.type === "AUTO_ENEMY_SPAWNED");
    const leftEnemy = leftward.enemies.find((enemy) => enemy.id === leftSpawn?.enemyId);
    assert.equal(leftSpawn?.direction, -1, "an exit to the left should produce a forward left-side spawn");
    assert.equal(leftEnemy?.enemyDefinitionId, "enemy_010", "leftward spawning should still obey the configured pool");
    assert.ok(leftSpawn.distanceBeyondScreen >= 40 && leftSpawn.distanceBeyondScreen <= 400, "leftward spawn distance should use the same off-screen band");

    const flying = createAutomaticEnemySpawnTestState({ enemyPool: "20", randomSeed: 88 });
    for (let step = 0; step < 62; step += 1) stepSimulation(flying, createInputFrame(), FIXED_DT);
    const flyingEnemy = flying.enemies.find((enemy) => enemy.autoSpawned);
    assert.equal(flyingEnemy?.enemyDefinitionId, "enemy_020", "flying catalog enemies should remain eligible for automatic spawning");
    assert.equal(flyingEnemy?.strategy, "bomber", "flying reinforcements should retain the strategy required by their locomotion");
    assert.equal(flyingEnemy?.alerted, true, "flying reinforcements should also begin aware of the player");
    assert.equal(flyingEnemy?.engaged, true, "flying reinforcements should begin engaged rather than idling at their spawn point");

    const disabled = createAutomaticEnemySpawnTestState({ probabilityPercent: 0 });
    for (let step = 0; step < 122; step += 1) stepSimulation(disabled, createInputFrame(), FIXED_DT);
    assert.equal(disabled.world.autoSpawnEnemies.rollCount, 0, "zero percent should keep the feature dormant");
    assert.equal(disabled.enemies.length, 0, "zero percent should never create an enemy");
}

