function testLevelOneUsesBakedHunterNavigationGraphs() {
    const level = JSON.parse(readFileSync("./assets/level_t01.json", "utf8"));
    assert.equal(level.navigationGraphs?.profiles?.length, 3, "level_t01 should contain shared baked profiles for goblin hunters, taller human hunters, and the Skeleton Caster");
    for (const graph of level.navigationGraphs.profiles) {
        assert.ok(graph.supportSignature, "each baked graph should include a geometry signature");
        assert.ok(graph.edges.some((edge) => edge.type === "jump"), "each baked graph should retain jump transitions");
        assert.ok(
            graph.edges.some((edge) => edge.type === "drop" && edge.walkOff === true),
            "each baked graph should retain deliberate walk-off drops"
        );
    }

    const graph = level.navigationGraphs.profiles.find((candidate) => candidate.profile.bodyWidth === 70 && candidate.profile.bodyHeight === 105);
    assert.ok(graph, "level_t01 should retain the goblin hunter mobility profile");
    assert.equal(graph.profile.runSpeed, 250, "the baked goblin hunter profile should match the authored nimble run speed");
    assert.equal(graph.profile.maxFallDistance, 600, "the baked goblin hunter profile should permit the authored long ledge descent");
    const casterGraph = level.navigationGraphs.profiles.find((candidate) => candidate.profile.bodyWidth === 72 && candidate.profile.bodyHeight === 164);
    assert.ok(casterGraph, "level_t01 should retain the Skeleton Caster's distinct pathing-projectile hunter profile");
    assert.equal(casterGraph.profile.runSpeed, 150, "the baked Skeleton Caster profile should match its authored run speed");
    assert.equal(casterGraph.profile.maxFallDistance, 600, "the baked Skeleton Caster profile should preserve its current fall tolerance");
    const humanGraph = level.navigationGraphs.profiles.find((candidate) => candidate.profile.bodyWidth === 67.5 && candidate.profile.bodyHeight === 194);
    assert.ok(humanGraph, "level_t01 should include the distinct tall-human hunter mobility profile");
    assert.equal(humanGraph.profile.runSpeed, 200, "the baked human hunter profile should match the authored human run speed");
    assert.equal(humanGraph.profile.jumpHeight, 200, "the baked human hunter profile should retain its authored human jump height");
    assert.equal(humanGraph.profile.maxFallDistance, 600, "the baked human hunter profile should permit the authored tall-ledge exits");
    assert.ok(
        humanGraph.edges.some((edge) => edge.from === "left_step_blockable_1" && edge.to === "start_ground_blockable_2" && edge.type === "jump" && edge.direction === "left"),
        "the tall-human graph should include the screenshot ledge jump back to the starter platform"
    );
    assert.ok(
        humanGraph.edges.some((edge) => edge.from === "left_step_blockable_1" && edge.type === "drop" && edge.direction === "right" && edge.walkOff === true),
        "the tall-human graph should also include a controlled right-hand walk-off from the screenshot ledge"
    );
    const pillarRoute = planEnemyNavigationRoute(
        graph.supports,
        "floor_cold_platform_001_blockable_2_nav_2",
        "floor_cold_platform_001_blockable_2_nav_1",
        {
            edgeMap: enemyNavigationEdgeMapFromFlat(graph.edges),
            startX: 2140,
            targetX: 1200
        }
    );
    assert.ok(pillarRoute, "the baked graph should route a hunter across and down from the central pillar");
    assert.ok(
        pillarRoute.edges.some((edge) => (
            edge.type === "drop" ||
            (edge.type === "jump" && edge.landingY > edge.launchY + 80)
        )),
        "the central-pillar route should include a deliberate descent rather than strand the hunter on top"
    );
    assert.ok(
        pillarRoute.edges[0].takeoffClearance >= graph.profile.bodyWidth * 0.54,
        "the approach jump should launch with body clearance instead of waiting until the hunter reaches the wall"
    );

    const state = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(state, level), true, "level_t01 should apply for baked graph verification");
    const manifests = new Map();
    for (const ref of level.atlasRefs || []) {
        const path = String(ref.manifest || "").replace(/^assets\//, "./assets/");
        manifests.set(ref.atlasId, { manifest: JSON.parse(readFileSync(path, "utf8")) });
    }
    assert.equal(applyAtlasManifestsToWorld(state, manifests), true, "level collision should apply before baked graph verification");
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    stepSimulation(state, createInputFrame(), FIXED_DT);
    const hunters = state.enemies.filter((enemy) => enemy.strategy === "hunter");
    assert.ok(hunters.length >= 5, "level_t01 should instantiate goblin, human, and Skeleton Caster hunters");
    assert.ok(hunters.every((enemy) => enemy.navigationGraphSource === "baked"), "hunters with matching mobility and geometry should consume their pre-baked graph");
    assert.equal(new Set(hunters.map((enemy) => enemy.navigationGraphId)).size, 3, "the three hunter body and mobility profiles should resolve to three distinct baked graphs");
}


function testHunterCrossesLevelOneCentralPillarAndJumpsDown() {
    const level = JSON.parse(readFileSync("./assets/level_t01.json", "utf8"));
    level.entities = level.entities.filter((entity) => entity.type !== "characterEnemy" || entity.id === "enemy_010_001");

    const state = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(state, level), true, "level_t01 should apply for the central-pillar traversal regression test");
    const manifests = new Map();
    for (const ref of level.atlasRefs || []) {
        const path = String(ref.manifest || "").replace(/^assets\//, "./assets/");
        manifests.set(ref.atlasId, { manifest: JSON.parse(readFileSync(path, "utf8")) });
    }
    assert.equal(applyAtlasManifestsToWorld(state, manifests), true, "level collision should apply for central-pillar traversal");
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    state.player.currentTransform.x = 1200;
    state.player.currentTransform.y = 844.2;
    state.player.onGround = true;
    state.player.wasOnGround = true;
    state.player.visible = true;

    const enemy = state.enemies.find((item) => item.id === "enemy_010_001");
    assert.ok(enemy, "level_t01 should instantiate the fireball goblin used by the central-pillar regression test");
    enemy.awarenessRange = 2000;
    enemy.facing = -1;

    let landedOnPillarTop = false;
    let launchedDownward = false;
    let landedOnLeftFloor = false;
    let glared = false;
    for (let frame = 0; frame < 380 && !landedOnLeftFloor; frame += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
        glared ||= enemy.aiState === "unreachable_glare";
        landedOnPillarTop ||= !enemy.airborne && enemy.currentSupportId === "object_036_001_blockable_1";
        launchedDownward ||= landedOnPillarTop
            && enemy.airborne
            && enemy.route?.[enemy.routeIndex]?.to === "floor_cold_platform_001_blockable_2_nav_1";
        landedOnLeftFloor ||= !enemy.airborne && enemy.currentSupportId === "floor_cold_platform_001_blockable_2_nav_1";
    }

    assert.equal(glared, false, "the hunter should not abandon a valid route across the central pillar");
    assert.equal(landedOnPillarTop, true, "the hunter should accept a safe full-body landing on the pillar top and replan");
    assert.equal(launchedDownward, true, "the hunter should deliberately jump down from the pillar top");
    assert.equal(landedOnLeftFloor, true, "the hunter should complete the route onto the lower floor");
    assert.equal(enemy.navigationFailureCount, 0, "safe alternate landings should not be counted as navigation failures");
}

