function addTestRocket(state, overrides = {}) {
    const projectile = {
        id: overrides.id || `test_rocket_${state.projectiles.length + 1}`,
        kind: "homingRocket",
        state: "launched",
        x: overrides.x ?? 0,
        y: overrides.y ?? 50,
        vx: overrides.vx ?? 12000,
        vy: overrides.vy ?? 0,
        targetId: overrides.targetId ?? null,
        upLaunchTimer: overrides.upLaunchTimer ?? 999,
        age: 0,
        lifetime: overrides.lifetime ?? 2,
        explosionTimer: 0,
        radius: overrides.radius ?? 6,
        damage: overrides.damage ?? 55,
        trail: []
    };
    state.projectiles.push(projectile);
    return projectile;
}

function testRebalancedEnemyHealthAndRocketHits() {
    const catalog = JSON.parse(readFileSync(new URL("../assets/ct_enemies_001.json", import.meta.url), "utf8"));
    const levelOne = JSON.parse(readFileSync(new URL("../assets/level_t01.json", import.meta.url), "utf8"));
    const profiles = [
        { id: "enemy_001", characterId: "ct_char_enemy_001", expectedHealth: 120, expectedHits: 4 },
        { id: "enemy_002", characterId: "ct_char_enemy_002", expectedHealth: 120, expectedHits: 4 },
        { id: "enemy_010", characterId: "ct_char_enemy_010", expectedHealth: 60, expectedHits: 2 },
        { id: "enemy_011", characterId: "ct_char_enemy_011", expectedHealth: 60, expectedHits: 2, placedInLevelOne: false },
        { id: "enemy_012", characterId: "ct_char_enemy_012", expectedHealth: 60, expectedHits: 2 },
        { id: "enemy_020", characterId: "ct_char_enemy_020", expectedHealth: 1, expectedHits: 1 },
        { id: "enemy_030", characterId: "ct_char_enemy_030", expectedHealth: 90, expectedHits: 3 },
        { id: "enemy_031", characterId: "ct_char_enemy_031", expectedHealth: 90, expectedHits: 3 },
        { id: "enemy_032", characterId: "ct_char_enemy_032", expectedHealth: 90, expectedHits: 3 },
        { id: "enemy_033", characterId: "ct_char_enemy_033", expectedHealth: 90, expectedHits: 3 }
    ];

    for (const profile of profiles) {
        const catalogHealth = catalog.enemies[profile.id].defaults.health;
        assert.equal(catalogHealth, profile.expectedHealth, `${profile.id} catalog health should match the revision-478 balance`);
        const placed = levelOne.entities.find((entity) => entity.characterId === profile.characterId);
        if (profile.placedInLevelOne !== false) {
            assert.ok(placed, `level_t01 should contain ${profile.characterId}`);
            assert.equal(placed.health, profile.expectedHealth, `${placed.id} should bake the same health as its catalog default`);
        }
    }

    for (const profile of profiles.filter((entry) => entry.id !== "enemy_020")) {
        const state = createInitialGameState();
        assert.equal(applyEditorLevelToWorld(state, {
            levelId: `balanced_health_${profile.id}`,
            testPlayerStart: { x: -200, y: 600 },
            entities: [{
                id: `target_${profile.id}`,
                type: "characterEnemy",
                characterId: profile.characterId,
                x: 180,
                y: 100,
                w: profile.id === "enemy_001" || profile.id === "enemy_002" ? 72 : (profile.id.startsWith("enemy_03") ? 60 : 70),
                h: profile.id === "enemy_001" || profile.id === "enemy_002" ? 164 : (profile.id.startsWith("enemy_03") ? 170 : 105),
                health: profile.expectedHealth,
                strategy: "sentry",
                facing: -1
            }]
        }), true, "balanced enemy-health test level should apply");
        state.world.solids = [];
        state.world.segments = [];
        state.world.collisionPolygons = [];
        state.story.portalIntro = null;
        state.story.portalExit = null;
        state.story.mailboxEvent = null;
        const enemy = state.enemies[0];

        for (let hit = 1; hit <= profile.expectedHits; hit += 1) {
            state.projectiles = [];
            addTestRocket(state, { id: `${profile.id}_standard_hit_${hit}`, damage: DEFAULT_TUNING.rocketProjectileDamage });
            stepSimulation(state, createInputFrame(), FIXED_DT);
            if (hit < profile.expectedHits) {
                assert.ok(enemy.health > 0, `${profile.id} should survive standard rocket hit ${hit}`);
                assert.notEqual(enemy.combatState, "dead", `${profile.id} should remain alive before hit ${profile.expectedHits}`);
            }
        }
        assert.equal(enemy.health, 0, `${profile.id} should reach zero HP on standard rocket hit ${profile.expectedHits}`);
        assert.equal(enemy.combatState, "dead", `${profile.id} should die exactly on standard rocket hit ${profile.expectedHits}`);
    }

    const fallbackState = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(fallbackState, {
        levelId: "default_enemy_health_90",
        testPlayerStart: { x: 0, y: 600 },
        entities: [{
            id: "new_monster_without_authored_health",
            type: "characterEnemy",
            characterId: "ct_char_enemy_001",
            x: 100,
            y: 600,
            strategy: "sentry"
        }]
    }), true, "missing-health enemy test level should apply");
    assert.equal(fallbackState.enemies[0].health, 90, "new monsters without authored health should default to 90 HP at runtime");
    assert.equal(fallbackState.enemies[0].maxHealth, 90, "new monsters without authored health should default to 90 maximum HP");

    const levelEditorHtml = readFileSync(new URL("../level-editor.html", import.meta.url), "utf8");
    const characterEditorHtml = readFileSync(new URL("../character-editor.html", import.meta.url), "utf8");
    assert.ok(levelEditorHtml.includes("health: 90,"), "new Level Editor enemy placements should start from the 90 HP fallback");
    assert.ok(levelEditorHtml.includes("finiteEditorNumber(rec.health, 90)"), "Level Editor enemy health inspector should fall back to 90 HP");
    assert.ok(characterEditorHtml.includes("Number(defaults.health) : 90"), "Puppet Forge should show 90 HP when a catalog entry has no authored health");
    assert.ok(characterEditorHtml.includes('els.enemyHealth.value.trim() === "" ? 90'), "Puppet Forge should save 90 HP when a new enemy health field is blank");
}

function testCharacterEnemyRocketCombat() {
    const state = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(state, {
        levelId: "enemy_combat_test",
        testPlayerStart: { x: -200, y: 600 },
        entities: [{
            id: "combat_guard",
            type: "characterEnemy",
            characterId: "ct_char_enemy_001",
            x: 180,
            y: 100,
            w: 72,
            h: 150,
            health: 100,
            strategy: "sentry",
            facing: -1,
            hurtDuration: 0.48,
            deathDuration: 1.18
        }, {
            id: "reserve_guard",
            type: "characterEnemy",
            characterId: "ct_char_enemy_001",
            x: 520,
            y: 100,
            w: 72,
            h: 150,
            health: 100,
            strategy: "sentry",
            facing: -1
        }]
    }), true, "enemy combat test level should apply");
    state.world.solids = [];
    state.world.segments = [];
    state.world.collisionPolygons = [];
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    state.camera.currentTransform.x = 160;
    state.camera.currentTransform.y = 430;
    state.camera.viewportWidth = 2000;

    const enemy = state.enemies.find((item) => item.id === "combat_guard");
    const target = state.targets.find((item) => item.enemyId === enemy.id);
    const reserveTarget = state.targets.find((item) => item.enemyId === "reserve_guard");
    enemy.combatState = "attacking";
    enemy.movementPhase = "attack";
    enemy.animationSlot = "attack";
    enemy.attackTimer = 0.3;
    enemy.attackHitApplied = false;
    enemy.awarenessRange = 1;
    enemy.awarenessTimer = 0;
    enemy.alerted = false;
    enemy.engaged = false;
    enemy.facing = 1;
    const impactPlayerX = state.player.currentTransform.x;
    const impactPlayerY = state.player.currentTransform.y;
    const first = addTestRocket(state, { id: "combat_hit_1" });
    stepSimulation(state, createInputFrame(), FIXED_DT);

    assert.equal(first.state, "exploding", "rocket should explode on the enemy body");
    assert.equal(enemy.health, 45, "first rocket should subtract its serialized damage");
    assert.equal(enemy.maxHealth, 100, "enemy maximum health should remain stable after damage");
    assert.equal(enemy.combatState, "hurt", "surviving enemy should enter hurt combat state");
    assert.equal(enemy.animationSlot, "hurt", "surviving Skeleton Guard should play the authored hurt clip");
    assert.equal(enemy.attackTimer, 0, "rocket hurt should interrupt an in-progress melee attack");
    assert.ok(enemy.hitFlashTimer > 0, "enemy hit should start a renderer-facing flash timer");
    assert.ok(enemy.healthBarTimer > 0, "enemy hit should temporarily reveal its health bar");
    assert.equal(enemy.alerted, true, "damage from Ignatius should alert an enemy even outside its awareness range");
    assert.equal(enemy.engaged, true, "damage from Ignatius should engage the enemy");
    assert.ok(enemy.awarenessTimer > 0, "damage awareness should persist beyond the impact frame");
    assert.equal(enemy.lastSeenPlayerX, impactPlayerX, "damage awareness should remember Ignatius's horizontal position at impact");
    assert.equal(enemy.lastSeenPlayerY, impactPlayerY, "damage awareness should remember Ignatius's vertical position at impact");
    assert.equal(enemy.facing, -1, "the damaged enemy should turn toward Ignatius");
    assert.equal(target.state, "active", "surviving enemy should remain a homing target");
    assert.ok(state.debug.lastEvents.some((event) => event.type === "ENEMY_DAMAGED" && event.enemyId === enemy.id), "damage should emit an enemy event");
    assert.ok(state.debug.lastEvents.some((event) => event.type === "ENEMY_ALERTED" && event.enemyId === enemy.id && event.reason === "player_damage"), "damage should emit an explicit player-damage alert event");

    state.projectiles = [];
    stepMany(state, Math.ceil(enemy.hurtDuration / FIXED_DT) + 2);
    assert.equal(enemy.combatState, "alive", "enemy should leave hurt state after the authored recoil duration");
    assert.equal(enemy.animationSlot, "idle", "guard enemy should return to idle after hurt recovery");

    const second = addTestRocket(state, { id: "combat_hit_2" });
    stepSimulation(state, createInputFrame(), FIXED_DT);
    assert.equal(second.state, "exploding", "lethal rocket should still resolve as an enemy impact");
    assert.equal(enemy.health, 0, "second rocket should defeat the damaged guard");
    assert.equal(enemy.combatState, "dead", "lethal damage should enter dead combat state");
    assert.equal(enemy.animationSlot, "death", "lethal damage should select the authored death clip");
    assert.equal(enemy.movementPhase, "dead", "defeated guard should stop patrol movement");
    assert.equal(enemy.currentTransform.alpha, 1, "defeated enemy should initially remain fully opaque");
    assert.equal(target.state, "inactive", "defeated enemy should leave the homing target pool");
    assert.equal(reserveTarget.state, "active", "other living enemies should remain targetable");
    assert.ok(state.debug.lastEvents.some((event) => event.type === "ENEMY_DEFEATED" && event.enemyId === enemy.id), "lethal damage should emit a defeat event");

    state.projectiles = [];
    state.camera.currentTransform.x = reserveTarget.x;
    state.camera.currentTransform.y = reserveTarget.y + 250;
    state.camera.viewportWidth = 2000;
    state.camera.viewportHeight = 1200;
    stepSimulation(state, createInputFrame({ weaponPressed: true, weaponHeld: true }), FIXED_DT);
    assert.equal(state.projectiles[0].targetId, reserveTarget.id, "new rockets should retarget the next visible living enemy");

    const deadX = enemy.currentTransform.x;
    state.projectiles = [];
    stepMany(state, 100);
    assert.equal(enemy.currentTransform.x, deadX, "defeated enemy should remain stationary");
    assert.equal(enemy.animationSlot, "death", "defeated enemy should remain on its non-looping death presentation");
    assert.equal(enemy.currentTransform.alpha, 1, "defeated enemy should remain fully opaque for the first two seconds");

    stepMany(state, 90);
    assert.ok(enemy.currentTransform.alpha > 0.5 && enemy.currentTransform.alpha < 0.75, "defeated enemy should fade gradually after the two-second hold");

    stepMany(state, 120);
    assert.equal(enemy.currentTransform.alpha, 0, "defeated enemy should be fully transparent after the three-second fade");
}

function testPassiveEnemyStaysPassiveWhenDamaged() {
    const enemyCatalog = JSON.parse(readFileSync(new URL("../assets/ct_enemies_001.json", import.meta.url), "utf8"));
    const state = createInitialGameState({ enemyCatalog });
    assert.equal(applyEditorLevelToWorld(state, {
        levelId: "passive_dummy_damage_test",
        testPlayerStart: { x: 520, y: 600 },
        entities: [{
            id: "training_dummy",
            type: "characterEnemy",
            enemyCatalogId: "enemy_900",
            x: 180,
            y: 100,
            facing: -1
        }]
    }), true, "passive dummy damage test level should apply");
    state.world.solids = [];
    state.world.segments = [];
    state.world.collisionPolygons = [];
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;

    const enemy = state.enemies.find((item) => item.id === "training_dummy");
    const target = state.targets.find((item) => item.enemyId === enemy.id);
    const rocket = addTestRocket(state, { id: "passive_dummy_hit" });
    stepSimulation(state, createInputFrame(), FIXED_DT);

    assert.equal(rocket.state, "exploding", "rocket should still impact the passive dummy");
    assert.equal(enemy.alerted, false, "passive dummy should not enter an alerted state when damaged");
    assert.equal(enemy.engaged, false, "passive dummy should not become engaged when damaged");
    assert.equal(target.state, "active", "damaged passive dummy should remain a valid homing target while alive");
    assert.ok(enemy.hitFlashTimer > 0, "passive dummy should still show the hit flash");

    const startX = enemy.currentTransform.x;
    const startY = enemy.currentTransform.y;
    for (let tick = 0; tick < 120; tick += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
    }
    approx(enemy.currentTransform.x, startX, 0.000001, "Passive strategy should remain horizontally stationary after damage");
    approx(enemy.currentTransform.y, startY, 0.000001, "Passive strategy should remain vertically stationary after damage");
    assert.equal(enemy.alerted, false, "Passive strategy should stay unalerted after damage");
    assert.equal(enemy.engaged, false, "Passive strategy should stay disengaged after damage");
    assert.equal(enemy.attackTimer, 0, "Passive strategy should never begin an attack after damage");
    assert.equal(enemy.movementPhase, "idle", "Passive strategy should remain in its idle movement phase");
}

function testAirborneEnemyDefersDeathUntilLanding() {
    const state = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(state, {
        levelId: "airborne_death_deferred_until_landing",
        testPlayerStart: { x: -300, y: 400 },
        entities: [{
            id: "jumping_guard",
            type: "characterEnemy",
            characterId: "ct_char_enemy_001",
            x: 120,
            y: 170,
            w: 72,
            h: 150,
            health: 30,
            strategy: "hunter",
            facing: 1,
            deathDuration: 1.18
        }]
    }), true, "airborne death-defer test level should apply");
    state.world.solids = [];
    state.world.collisionPolygons = [];
    state.world.segments = [{
        id: "landing_floor",
        kind: "walkable",
        x1: -500,
        y1: 400,
        x2: 500,
        y2: 400
    }];
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;

    const enemy = state.enemies.find((item) => item.id === "jumping_guard");
    const target = state.targets.find((item) => item.enemyId === enemy.id);
    enemy.airborne = true;
    enemy.supportId = null;
    enemy.ridingPlatformId = null;
    enemy.currentSupportId = null;
    enemy.airTraversalType = "jump";
    enemy.airSourceSupportId = null;
    enemy.airSourceObstacleId = null;
    enemy.airTargetSupportId = null;
    enemy.airTimer = 0;
    enemy.velocityX = 45;
    enemy.velocityY = -120;
    enemy.combatState = "alive";
    enemy.state = "idle";
    enemy.movementPhase = "jump";
    enemy.animationSlot = "walk";

    const impactX = enemy.currentTransform.x;
    const impactY = enemy.currentTransform.y;
    const rocket = addTestRocket(state, {
        id: "airborne_lethal_hit",
        x: 0,
        y: 50,
        vx: 12000,
        damage: 30
    });
    stepSimulation(state, createInputFrame(), FIXED_DT);

    assert.equal(rocket.state, "exploding", "lethal rocket should still resolve against an airborne mob");
    assert.equal(enemy.health, 0, "airborne lethal damage should be recorded immediately");
    assert.equal(enemy.deathPendingLanding, true, "ground mob death should be deferred while it is airborne");
    assert.equal(enemy.combatState, "death_pending_landing", "airborne mob should enter the explicit landing-pending state");
    assert.notEqual(enemy.animationSlot, "death", "death animation must not start in mid-jump");
    assert.equal(enemy.deathTimer, 0, "death animation time must not be consumed before landing");
    assert.equal(target.state, "inactive", "a mortally hit airborne mob should leave the homing target pool");
    assert.ok(state.debug.lastEvents.some((event) => (
        event.type === "ENEMY_DEFEATED" &&
        event.enemyId === enemy.id &&
        event.deferredUntilLanding === true
    )), "defeat diagnostics should record that presentation is deferred until landing");

    stepMany(state, 8);
    assert.equal(enemy.airborne, true, "the test mob should still be completing its jump shortly after the lethal hit");
    assert.equal(enemy.deathPendingLanding, true, "death should remain pending throughout the airborne arc");
    assert.notEqual(enemy.animationSlot, "death", "the normal locomotion pose should continue through the airborne arc");
    assert.ok(enemy.currentTransform.x > impactX, "the mob should preserve its horizontal jump momentum after the lethal hit");
    assert.notEqual(enemy.currentTransform.y, impactY, "the mob should continue its vertical jump trajectory after the lethal hit");

    let landed = false;
    for (let tick = 0; tick < 240; tick += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
        if (enemy.airborne) {
            assert.notEqual(enemy.animationSlot, "death", "death animation must remain suppressed until the landing tick");
            continue;
        }
        landed = true;
        break;
    }

    assert.equal(landed, true, "the mortally hit mob should complete the jump and land on ordinary collision geometry");
    assert.ok(Math.abs(enemy.currentTransform.y - 400) < 0.01, `the mob should land cleanly on the floor before dying (${enemy.currentTransform.y})`);
    assert.equal(enemy.deathPendingLanding, false, "landing should consume the deferred-death state");
    assert.equal(enemy.combatState, "dead", "the mob should become dead only after landing");
    assert.equal(enemy.animationSlot, "death", "landing should start the authored death animation");
    assert.ok(enemy.deathTimer > 1.1, "the death animation should begin with its full duration after landing");
    assert.equal(enemy.velocityX, 0, "landing death should not retain airborne horizontal momentum");
    assert.equal(enemy.velocityY, 0, "landing death should not retain airborne vertical momentum");
    assert.equal(enemy.supportId, "landing_floor", "the dying mob should retain its landing support identity");

    stepMany(state, 100);
    assert.ok(Math.abs(enemy.currentTransform.y - 400) < 0.01, "the grounded death animation should not be followed by a second corpse drop");
}

function testEnemyContactDamageUsesIndependentInvulnerability() {
    const state = createInitialGameState({
        tuning: {
            playerDamageInvulnerabilitySeconds: 0.45,
            playerContactDamageInvulnerabilitySeconds: 0.45,
            healthRegenRate: 0
        }
    });
    assert.equal(applyEditorLevelToWorld(state, {
        levelId: "enemy_contact_damage_test",
        testPlayerStart: { x: 0, y: 600 },
        entities: [{
            id: "contact_guard",
            type: "characterEnemy",
            characterId: "ct_char_enemy_001",
            x: 0,
            y: 600,
            w: 72,
            h: 150,
            strategy: "sentry",
            health: 100,
            attackDamage: 40,
            projectileDamage: 80,
            attackRange: 92,
            attackVerticalRange: 110,
            attackDuration: 0.3,
            attackHitTime: 0.1,
            attackCooldown: 0.4
        }]
    }), true, "contact damage test level should apply");
    state.world.solids = [];
    state.world.segments = [{ id: "contact_floor", kind: "walkable", x1: -200, y1: 600, x2: 300, y2: 600 }];
    state.world.collisionPolygons = [];
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    state.player.currentTransform.x = 0;
    state.player.currentTransform.y = 600;
    state.player.onGround = true;

    const before = state.health.amount;
    stepSimulation(state, createInputFrame(), FIXED_DT);
    approx(before - state.health.amount, 20, 0.000001, "contact damage should be one quarter of the stronger ranged or melee damage");
    assert.ok(state.health.contactInvulnerabilityTimer > 0, "contact damage should start its own cooldown");
    assert.equal(state.health.invulnerabilityTimer, 0, "contact damage must not consume ordinary attack invulnerability");

    const afterContact = state.health.amount;
    stepSimulation(state, createInputFrame(), FIXED_DT);
    approx(state.health.amount, afterContact, 0.000001, "continued overlap should be blocked by contact-only invulnerability");

    const meleeResult = damagePlayer(state, 10, "same_frame_melee");
    approx(meleeResult.damage, 10, 0.000001, "ordinary melee damage should still land during contact invulnerability");
    const contactTimerBefore = state.health.contactInvulnerabilityTimer;
    const contactResult = damagePlayer(state, 20, "same_frame_contact", {
        invulnerabilityTimerKey: "contactInvulnerabilityTimer",
        invulnerabilitySeconds: state.tuning.playerContactDamageInvulnerabilitySeconds
    });
    assert.equal(contactResult.damage, 0, "the independent contact cooldown should still block another contact hit");
    assert.ok(contactTimerBefore > 0, "contact timer should remain active during the independent melee hit");
}

function testCharacterEnemyMeleeAttack() {
    const state = createInitialGameState({
        tuning: {
            healthRegenDelay: 0.4,
            healthRegenRate: 20,
            playerDamageInvulnerabilitySeconds: 0.3
        }
    });
    assert.equal(applyEditorLevelToWorld(state, {
        levelId: "enemy_melee_test",
        testPlayerStart: { x: 0, y: 600 },
        entities: [{
            id: "melee_guard",
            type: "characterEnemy",
            characterId: "ct_char_enemy_001",
            x: 76,
            y: 600,
            w: 72,
            h: 150,
            facing: -1,
            strategy: "sentry",
            health: 100,
            attackDamage: 25,
            attackRange: 92,
            attackVerticalRange: 110,
            attackDuration: 0.3,
            attackHitTime: 0.1,
            attackCooldown: 0.4,
            attackKnockbackX: 280,
            attackKnockbackY: -210
        }]
    }), true, "melee combat test level should apply");
    state.world.solids = [];
    state.world.segments = [{ id: "melee_floor", kind: "walkable", x1: -200, y1: 600, x2: 300, y2: 600 }];
    state.world.collisionPolygons = [];
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    state.player.currentTransform.x = 0;
    state.player.currentTransform.y = 600;
    state.player.onGround = true;
    state.player.wasOnGround = true;

    const enemy = state.enemies.find((item) => item.id === "melee_guard");
    stepSimulation(state, createInputFrame(), FIXED_DT);
    assert.equal(enemy.combatState, "attacking", "guard should enter an explicit attack combat state");
    assert.equal(enemy.animationSlot, "attack", "guard should use the authored attack clip");
    assert.equal(enemy.facing, -1, "guard should face Ignatius when the attack begins");
    assert.ok(state.debug.lastEvents.some((event) => event.type === "ENEMY_ATTACK_STARTED"), "attack start should emit an event");

    stepMany(state, 7);
    approx(state.health.amount, 75, 0.001, "sword hit should subtract authored damage once");
    assert.ok(state.health.invulnerabilityTimer > 0, "successful hit should start player damage invulnerability");
    assert.ok(state.player.vx < -200, "sword hit should knock Ignatius away from the attacker");
    assert.ok(state.player.vy < 0, "sword hit should lift Ignatius with authored knockback");
    assert.ok(state.debug.lastEvents.some((event) => event.type === "ENEMY_ATTACK_HIT"), "successful sword hit should emit a hit event");

    const healthAfterHit = state.health.amount;
    stepMany(state, 8);
    approx(state.health.amount, healthAfterHit, 0.001, "one sword swing should never deal damage more than once");
    stepMany(state, 20);
    assert.notEqual(enemy.combatState, "attacking", "guard should leave attack state when the authored clip duration ends");

    state.player.currentTransform.x = -300;
    state.player.currentTransform.y = 600;
    state.player.vx = 0;
    state.player.vy = 0;
    state.player.onGround = true;
    stepMany(state, 30);
    assert.ok(state.health.amount > healthAfterHit, "health should begin regenerating after the configured delay");
    assert.ok(
        state.debug.lastEvents.some((event) => event.type === "PLAYER_HEALTH_REGEN_STARTED"),
        "health regeneration should emit presentation feedback"
    );
}

