            attackRange: 340,
            attackVerticalRange: 180,
            attackDuration: 0.4,
            attackHitTime: 0.1,
            attackCooldown: 0.12,
            projectileCooldown: 0.8,
            projectileKind: "fireball",
            projectileSpeed: 260,
